1	// Package vae implements Qwen-Image-2.1's autoencoder on the CPU — the
2	// 64-channel, 16x-spatial, RGBA-native Wan-lineage design — validated
3	// against reference/out/qi21vae stage by stage.
4	//
5	// The reference (reference/qwenimage21/autoencoder_kl_qwenimage21.py) is a
6	// *video* VAE run here at a single frame, and the port folds the temporal
7	// dimension away rather than carrying it. What "T=1" means, made explicit
8	// because each is a numeric behaviour the dumps pin:
9	//
10	//   - every causal 3D conv is a plain 2D conv (the reference's own image
11	//     specialization squeezes the frame axis and refuses a feature cache);
12	//   - the time_conv weights inside the 3D resamplers exist in the checkpoint
13	//     and never run — on the first chunk the reference skips them;
14	//   - AvgDown3D with a temporal factor zero-pads the missing frame *in
15	//     front* and means it in, so half of a temporal down-shortcut's
16	//     contributions are zeros. That is what the trained weights expect; it
17	//     is not a bug to fix;
18	//   - DupUp3D duplicates the frame temporally and `first_chunk` keeps only
19	//     the last copy, so only the spatial duplication survives.
20	//
21	// Norms are not the group norms of z-image's VAE: RMS_norm here is an L2
22	// normalize *across channels per pixel* (F.normalize over dim 1, eps 1e-12),
23	// scaled by sqrt(C) and a per-channel gamma. Every residual block is
24	// pre-norm silu-conv twice with a 1x1 (or identity) shortcut, and each
25	// down/up block carries a *parameter-free* resampling shortcut around its
26	// whole body — the "is_residual" design.
27	//
28	// Tensors are zimage/vae's NCHW [1, C, H, W] float32; that package's Conv2D
29	// (whose Pad/PadEnd/Stride were built for the identical (0,1,0,1)+stride-2
30	// downsampler) does the convolving.
31	package vae
32	
33	import (
34		"fmt"
35		"math"
36	
37		zvae "strix-halo-vulkan/zimage/vae"
38	)
39	
40	// ChannelNorm is the reference's RMS_norm: per pixel, the channel vector is
41	// L2-normalized (norm clamped below at 1e-12), scaled by sqrt(C) and a
42	// per-channel gamma. Mean is not subtracted.
43	type ChannelNorm struct {
44		Gamma []float32
45	}
46	
47	// Apply returns a normalized copy.
48	func (n *ChannelNorm) Apply(x *zvae.Tensor) (*zvae.Tensor, error) {
49		if x.C != len(n.Gamma) {
50			return nil, fmt.Errorf("qvae: channel norm of width %d over %d channels", len(n.Gamma), x.C)
51		}
52		out := zvae.NewTensor(x.N, x.C, x.H, x.W)
53		scale := math.Sqrt(float64(x.C))
54		plane := x.H * x.W
55		for i := 0; i < plane; i++ {
56			var sum float64
57			for c := 0; c < x.C; c++ {
58				v := float64(x.Data[c*plane+i])
59				sum += v * v
60			}
61			s := scale / math.Max(math.Sqrt(sum), 1e-12)
62			for c := 0; c < x.C; c++ {
63				out.Data[c*plane+i] = float32(float64(x.Data[c*plane+i]) * s * float64(n.Gamma[c]))
64			}
65		}
66		return out, nil
67	}
68	
69	// ResBlock is one residual block: pre-norm silu conv, twice, plus a 1x1 (or
70	// identity) shortcut.
71	type ResBlock struct {
72		Norm1, Norm2 ChannelNorm
73		Conv1, Conv2 zvae.Conv2D
74		Shortcut     *zvae.Conv2D // nil when in == out
75	}
76	
77	func (b *ResBlock) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
78		h := x
79		if b.Shortcut != nil {
80			var err error
81			if h, err = b.Shortcut.Apply(x); err != nil {
82				return nil, err
83			}
84		}
85		t, err := b.Norm1.Apply(x)
86		if err != nil {
87			return nil, err
88		}
89		zvae.SiLUInPlace(t)
90		if t, err = b.Conv1.Apply(t); err != nil {
91			return nil, err
92		}
93		if t, err = b.Norm2.Apply(t); err != nil {
94			return nil, err
95		}
96		zvae.SiLUInPlace(t)
97		if t, err = b.Conv2.Apply(t); err != nil {
98			return nil, err
99		}
100		if b.Shortcut != nil {
101			return zvae.AddInPlace(t, h)
102		}
103		return zvae.AddInPlace(t, x)
104	}
105	
106	// Attention is the mid block's single-head spatial self-attention: channel
107	// norm, a 1x1 qkv conv, softmax(q kᵀ/√C) v over the H*W tokens, a 1x1
108	// projection, and the residual.
109	type Attention struct {
110		Norm      ChannelNorm
111		QKV, Proj zvae.Conv2D
112	}
113	
114	func (a *Attention) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
115		normed, err := a.Norm.Apply(x)
116		if err != nil {
117			return nil, err
118		}
119		qkv, err := a.QKV.Apply(normed)
120		if err != nil {
121			return nil, err
122		}
123		C, plane := x.C, x.H*x.W
124		q := qkv.Data[:C*plane]
125		k := qkv.Data[C*plane : 2*C*plane]
126		v := qkv.Data[2*C*plane:]
127		scale := 1 / math.Sqrt(float64(C))
128	
129		ctx := zvae.NewTensor(1, C, x.H, x.W)
130		scores := make([]float64, plane)
131		for qi := 0; qi < plane; qi++ {
132			max := math.Inf(-1)
133			for ki := 0; ki < plane; ki++ {
134				var dot float64
135				for c := 0; c < C; c++ {
136					dot += float64(q[c*plane+qi]) * float64(k[c*plane+ki])
137				}
138				scores[ki] = dot * scale
139				if scores[ki] > max {
140					max = scores[ki]
141				}
142			}
143			var sum float64
144			for ki := range scores {
145				scores[ki] = math.Exp(scores[ki] - max)
146				sum += scores[ki]
147			}
148			for c := 0; c < C; c++ {
149				var acc float64
150				for ki := 0; ki < plane; ki++ {
151					acc += scores[ki] * float64(v[c*plane+ki])
152				}
153				ctx.Data[c*plane+qi] = float32(acc / sum)
154			}
155		}
156		out, err := a.Proj.Apply(ctx)
157		if err != nil {
158			return nil, err
159		}
160		return zvae.AddInPlace(out, x)
161	}
162	
163	// Mid is resnet, attention, resnet at the innermost resolution.
164	type Mid struct {
165		Res1 ResBlock
166		Attn Attention
167		Res2 ResBlock
168	}
169	
170	func (m *Mid) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
171		x, err := m.Res1.Forward(x)
172		if err != nil {
173			return nil, err
174		}
175		if x, err = m.Attn.Forward(x); err != nil {
176			return nil, err
177		}
178		return m.Res2.Forward(x)
179	}
180	
181	// AvgDown is the parameter-free downsampling shortcut: space-to-channel at
182	// the spatial factor, the missing temporal frame zero-padded in front, and
183	// groups of channels averaged down to the output width. FactorT 1 and
184	// FactorS 1 make it the identity, which is what the last encoder block has.
185	type AvgDown struct {
186		In, Out          int
187		FactorT, FactorS int
188	}
189	
190	func (d *AvgDown) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
191		if x.C != d.In {
192			return nil, fmt.Errorf("qvae: avg-down expects %d channels, got %d", d.In, x.C)
193		}
194		fs, ft := d.FactorS, d.FactorT
195		factor := ft * fs * fs
196		group := d.In * factor / d.Out
197		outH, outW := x.H/fs, x.W/fs
198		out := zvae.NewTensor(1, d.Out, outH, outW)
199		// At T=1 a temporal factor of 2 pads one zero frame in front: temporal
200		// slot 0 is the zero frame and only slot ft-1 holds the image.
201		for o := 0; o < d.Out; o++ {
202			dst := out.Plane(0, o)
203			for g := 0; g < group; g++ {
204				idx := o*group + g
205				c := idx / factor
206				rem := idx % factor
207				kt := rem / (fs * fs)
208				fh := rem / fs % fs
209				fw := rem % fs
210				if kt != ft-1 {
211					continue // the zero-padded frame contributes nothing
212				}
213				src := x.Plane(0, c)
214				for oh := 0; oh < outH; oh++ {
215					for ow := 0; ow < outW; ow++ {
216						dst[oh*outW+ow] += src[(oh*fs+fh)*x.W+(ow*fs+fw)]
217					}
218				}
219			}
220			inv := 1 / float32(group)
221			for i := range dst {
222				dst[i] *= inv
223			}
224		}
225		return out, nil
226	}
227	
228	// DupUp is the parameter-free upsampling shortcut: channels replicated and
229	// redistributed channel-to-space. At T=1 the reference expands the frame
230	// axis by FactorT and `first_chunk` keeps only the last copy, so only the
231	// spatial duplication survives — but *which* source channel feeds an output
232	// pixel still depends on FactorT through the replication layout.
233	type DupUp struct {
234		In, Out int
235		FactorT int
236	}
237	
238	func (u *DupUp) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
239		if x.C != u.In {
240			return nil, fmt.Errorf("qvae: dup-up expects %d channels, got %d", u.In, x.C)
241		}
242		const fs = 2
243		factor := u.FactorT * fs * fs
244		repeats := u.Out * factor / u.In
245		out := zvae.NewTensor(1, u.Out, x.H*fs, x.W*fs)
246		for o := 0; o < u.Out; o++ {
247			dst := out.Plane(0, o)
248			for i := 0; i < fs; i++ {
249				for j := 0; j < fs; j++ {
250					flat := ((o*u.FactorT+(u.FactorT-1))*fs+i)*fs + j
251					src := x.Plane(0, flat/repeats)
252					for h := 0; h < x.H; h++ {
253						for w := 0; w < x.W; w++ {
254							dst[(h*fs+i)*out.W+(w*fs+j)] = src[h*x.W+w]
255						}
256					}
257				}
258			}
259		}
260		return out, nil
261	}
262	
263	// Resample is the learned half of a down/up block's resampling: nearest 2x
264	// then a 3x3 conv going up, a (0,1,0,1) zero-pad and a stride-2 3x3 going
265	// down. The 3D variants' time_conv never runs at T=1.
266	type Resample struct {
267		Up   bool
268		Conv zvae.Conv2D
269	}
270	
271	func (r *Resample) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
272		if r.Up {
273			return r.Conv.Apply(zvae.UpsampleNearest2x(x))
274		}
275		return r.Conv.Apply(x)
276	}
277	
278	// DownBlock is one encoder stage: the residual blocks and learned
279	// downsampler, plus the AvgDown shortcut around the whole body.
280	type DownBlock struct {
281		Resnets  []ResBlock
282		Down     *Resample // nil on the last block
283		Shortcut AvgDown
284	}
285	
286	func (b *DownBlock) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
287		short, err := b.Shortcut.Forward(x)
288		if err != nil {
289			return nil, err
290		}
291		for i := range b.Resnets {
292			if x, err = b.Resnets[i].Forward(x); err != nil {
293				return nil, err
294			}
295		}
296		if b.Down != nil {
297			if x, err = b.Down.Forward(x); err != nil {
298				return nil, err
299			}
300		}
301		return zvae.AddInPlace(x, short)
302	}
303	
304	// UpBlock is one decoder stage: the residual blocks and learned upsampler,
305	// plus the DupUp shortcut. The last block has neither.
306	type UpBlock struct {
307		Resnets  []ResBlock
308		Up       *Resample
309		Shortcut *DupUp
310	}
311	
312	func (b *UpBlock) Forward(x *zvae.Tensor) (*zvae.Tensor, error) {
313		in := x
314		var err error
315		for i := range b.Resnets {
316			if x, err = b.Resnets[i].Forward(x); err != nil {
317				return nil, err
318			}
319		}
320		if b.Up != nil {
321			if x, err = b.Up.Forward(x); err != nil {
322				return nil, err
323			}
324		}
325		if b.Shortcut != nil {
326			short, err := b.Shortcut.Forward(in)
327			if err != nil {
328				return nil, err
329			}
330			return zvae.AddInPlace(x, short)
331		}
332		return x, nil
333	}
334	
335	// Decoder decodes denormalized latents [1, z, h, w] to an RGBA image
336	// [1, 4, 16h, 16w] in [-1, 1] (the reference clamps).
337	type Decoder struct {
338		PostQuant zvae.Conv2D // 1x1, z -> z
339		ConvIn    zvae.Conv2D
340		Mid       Mid
341		Ups       []UpBlock
342		NormOut   ChannelNorm
343		ConvOut   zvae.Conv2D
344	
345		// Tap, when set, sees each stage's output by name — the stagewise test
346		// walks the dump's hooks with it. Nil costs nothing.
347		Tap func(name string, t *zvae.Tensor)
348	}
349	
350	func (d *Decoder) tap(name string, t *zvae.Tensor) {
351		if d.Tap != nil {
352			d.Tap(name, t)
353		}
354	}
355	
356	// Decode runs the decoder.
357	func (d *Decoder) Decode(z *zvae.Tensor) (*zvae.Tensor, error) {
358		x, err := d.PostQuant.Apply(z)
359		if err != nil {
360			return nil, err
361		}
362		if x, err = d.ConvIn.Apply(x); err != nil {
363			return nil, err
364		}
365		d.tap("conv_in", x)
366		if x, err = d.Mid.Forward(x); err != nil {
367			return nil, err
368		}
369		d.tap("mid_block", x)
370		for i := range d.Ups {
371			if x, err = d.Ups[i].Forward(x); err != nil {
372				return nil, fmt.Errorf("qvae: up block %d: %w", i, err)
373			}
374			d.tap(fmt.Sprintf("up_blocks.%d", i), x)
375		}
376		if x, err = d.NormOut.Apply(x); err != nil {
377			return nil, err
378		}
379		d.tap("norm_out", x)
380		zvae.SiLUInPlace(x)
381		d.tap("nonlinearity", x)
382		if x, err = d.ConvOut.Apply(x); err != nil {
383			return nil, err
384		}
385		d.tap("conv_out", x)
386		for i, v := range x.Data {
387			if v > 1 {
388				x.Data[i] = 1
389			} else if v < -1 {
390				x.Data[i] = -1
391			}
392		}
393		return x, nil
394	}
395	
396	// Encoder encodes an RGBA image [1, 4, H, W] in [-1, 1] to the posterior
397	// *mode* [1, z, H/16, W/16] — the pipeline's argmax path; sampling would
398	// break seed reproducibility and is not implemented.
399	type Encoder struct {
400		ConvIn  zvae.Conv2D
401		Downs   []DownBlock
402		Mid     Mid
403		NormOut ChannelNorm
404		ConvOut zvae.Conv2D // -> 2z: mean then logvar
405		Quant   zvae.Conv2D // 1x1, 2z -> 2z
406	
407		Tap func(name string, t *zvae.Tensor)
408	}
409	
410	func (e *Encoder) tap(name string, t *zvae.Tensor) {
411		if e.Tap != nil {
412			e.Tap(name, t)
413		}
414	}
415	
416	// Encode returns the posterior mode: the mean half of the quantized output.
417	func (e *Encoder) Encode(img *zvae.Tensor) (*zvae.Tensor, error) {
418		x, err := e.ConvIn.Apply(img)
419		if err != nil {
420			return nil, err
421		}
422		e.tap("conv_in", x)
423		for i := range e.Downs {
424			if x, err = e.Downs[i].Forward(x); err != nil {
425				return nil, fmt.Errorf("qvae: down block %d: %w", i, err)
426			}
427			e.tap(fmt.Sprintf("down_blocks.%d", i), x)
428		}
429		if x, err = e.Mid.Forward(x); err != nil {
430			return nil, err
431		}
432		e.tap("mid_block", x)
433		if x, err = e.NormOut.Apply(x); err != nil {
434			return nil, err
435		}
436		e.tap("norm_out", x)
437		zvae.SiLUInPlace(x)
438		e.tap("nonlinearity", x)
439		if x, err = e.ConvOut.Apply(x); err != nil {
440			return nil, err
441		}
442		e.tap("conv_out", x)
443		if x, err = e.Quant.Apply(x); err != nil {
444			return nil, err
445		}
446		mode := zvae.NewTensor(1, x.C/2, x.H, x.W)
447		copy(mode.Data, x.Data[:len(mode.Data)])
448		return mode, nil
449	}
