171	// engine is the device-side machinery a convolution graph runs on.
172	//
173	// It is its own type because this package now holds *two* convolution graphs
174	// -- the AutoencoderKL decoder and taef1's preview decoder (tiny_gpu.go) --
175	// and everything below the graph is the same for both: four buffers under one
176	// descriptor layout, the pipelines built over that layout, the fp32 weight
177	// arena and its fp16 fragment-tile companion, and stage 8's implicit-GEMM
178	// convolution with its packing pass. What each decoder adds on top is its own
179	// kernels and its own graph.
180	type engine struct {
181		dev  *vk.Device
182		wbuf *vk.Buffer
183		abuf *vk.Buffer
184		// The fp16 pair, allocated only on the matrix-core path (stage 7): the
185		// activation arena the mid block's operands are packed into, and the four
186		// projection weights in their fragment-tile layout.
