268	// NewGPUDecoder uploads a loaded decoder's weights and builds its pipelines
269	// with the default kernels. latentH/latentW size the activation arena, which
270	// is allocated once for the largest tensor the graph will hold.
271	func NewGPUDecoder(dev *vk.Device, cpu *Decoder, latentH, latentW int) (*GPUDecoder, error) {
272		return NewGPUDecoderOpts(dev, cpu, latentH, latentW, Options{})
273	}
274	
275	// NewGPUDecoderOpts is NewGPUDecoder with the mid block's kernels named,
276	// which is what the ladder in cmd/vaebench sweeps and what the negative
277	// controls in the tests select.
278	func NewGPUDecoderOpts(dev *vk.Device, cpu *Decoder, latentH, latentW int, opt Options) (*GPUDecoder, error) {
279		g := &GPUDecoder{engine: newEngine(dev), cpu: cpu}
280		if err := g.engine.chooseKernels(opt); err != nil {
281			return nil, err
282		}
283	
284		g.flattenWeights()
285	
286		wbytes := len(g.weights.data) * 4
287		var err error
288		if g.wbuf, err = dev.NewBuffer(wbytes); err != nil {
289			g.Destroy()
290			return nil, fmt.Errorf("vae: weight buffer (%d MB): %w", wbytes>>20, err)
291		}
292		g.wbuf.WriteFloat32(g.weights.data)
293	
294		if g.f16() {
295			var w16 []uint16
296			if g.wmma() {
297				w16 = g.stageProjections(w16, cpu.Mid.Attn)
298			}
299			if g.convCores() {
300				w16 = g.stageConvWeights(w16)
301			}
302			if g.w16buf, err = dev.NewBuffer(len(w16) * 2); err != nil {
303				g.Destroy()
304				return nil, fmt.Errorf("vae: fp16 weight buffer (%d MB): %w", (len(w16)*2)>>20, err)
305			}
306			g.w16buf.WriteUint16At(0, w16)
307		}
308	
309		// Measure both arenas by recording the graph once with a throwaway plan.
310		need, hneed, err := g.planSize(latentH, latentW)
311		if err != nil {
312			g.Destroy()
313			return nil, err
314		}
315		if g.abuf, err = dev.NewBuffer(int(need) * 4); err != nil {
316			g.Destroy()
317			return nil, fmt.Errorf("vae: activation buffer (%d MB): %w", (int(need)*4)>>20, err)
318		}
319		// The fp16 arena is allocated even when it is empty, because it is bound
320		// to every pipeline: one descriptor layout across the graph is what lets
321		// vk.DispatchMultiTimed record it into a single command buffer.
322		if g.hbuf, err = dev.NewBuffer(max(int(hneed), 64) * 2); err != nil {
323			g.Destroy()
324			return nil, fmt.Errorf("vae: fp16 activation buffer (%d MB): %w", (int(hneed)*2)>>20, err)
325		}
326		// Zeroed once. Both passes that write it cover their own pad rows, so
327		// this is hygiene rather than an invariant -- but an operand arena that
328		// has never held anything cannot turn a stale bit pattern into an
329		// infinity, and one infinity in a row of A makes that whole row of the
330		// GEMM's output a NaN (stage 6).
331		g.hbuf.WriteFloat32(make([]float32, g.hbuf.Size()/4))
332		if g.w16buf == nil {
333			if g.w16buf, err = dev.NewBuffer(64); err != nil {
334				g.Destroy()
335				return nil, fmt.Errorf("vae: fp16 weight placeholder: %w", err)
336			}
337		}
338	
339		set := map[string][]byte{}
340		for name, spirv := range shaderSet {
341			set[name] = spirv
342		}
343		if g.wmma() {
344			for name, spirv := range wmmaShaderSet {
345				set[name] = spirv
346			}
347		}
348		if g.convCores() {
349			// The packing pass belongs to the chosen build, because one of the
350			// controls is a wrong pack rather than a wrong kernel (gpu_conv.go).
351			set["pack_conv"] = g.conv.packSpirv()
352		}
353		bufs := g.bufs()
354		pcSize := uint32(unsafe.Sizeof(pushConstants{}))
355		for name, spirv := range set {
356			if err := g.pipeline(name, spirv, vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize}); err != nil {
357				g.Destroy()
358				return nil, err
359			}
360		}
361		if g.wmma() {
362			// Both matrix-core kernels map gl_SubgroupID onto a wave grid, so
363			// their wave size is pinned rather than assumed: at the wrong size a
364			// workgroup holds the wrong number of waves and half of them write
365			// outside the tile.
366			if err := g.pipeline("attn_wmma", g.attn.spirv, vk.PipelineSpec{
367				Buffers: bufs, PushConstantSize: pcSize, RequiredSubgroupSize: g.attn.wave,
368			}); err != nil {
369				g.Destroy()
370				return nil, err
371			}
372			spec := vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize}
373			if g.gemm.waves > 1 {
374				spec.RequiredSubgroupSize = 64
375			}
376			if err := g.pipeline("gemm", g.gemm.spirv, spec); err != nil {
377				g.Destroy()
378				return nil, err
379			}
380		}
381		if g.convCores() {
382			// Pinned at both sizes, not only at 32: the kernel derives its wave's
383			// tile from gl_SubgroupID against a compile-time wave grid, so a
384			// workgroup holding a different number of waves than the build assumes
385			// writes outside its tile at either size.
386			if err := g.pipeline("conv_wmma", g.conv.spirv, vk.PipelineSpec{
387				Buffers: bufs, PushConstantSize: pcSize, RequiredSubgroupSize: g.conv.wave,
388			}); err != nil {
389				g.Destroy()
390				return nil, err
391			}
392		}
393		return g, nil
394	}
395	
396	// chooseKernels resolves Options against what the device can actually do.
397	// The mid block and the convolutions are resolved separately, so that a
398	// caller can narrow one and not the other -- which is what the tests that
399	// hold each path to the one it replaced need.
400	//
401	// It is on the engine because both graphs with a mid block -- the decoder's
402	// and the encoder's -- resolve the same three choices the same way.
403	func (g *engine) chooseKernels(opt Options) error {
404		if !hasMatrixCores(g.dev) {
405			if opt.Attn != "" && opt.Attn != AttnScalar {
406				return fmt.Errorf("vae: attention kernel %q needs fp16, cooperative matrices and subgroup size control", opt.Attn)
407			}
408			if opt.Conv != "" && opt.Conv != ConvScalar {
409				return fmt.Errorf("vae: conv kernel %q needs fp16, cooperative matrices and subgroup size control", opt.Conv)
410			}
411			return nil
412		}
413		if opt.Attn != AttnScalar {
414			attn := opt.Attn
415			if attn == "" {
416				attn = DefaultAttnKernel
417			}
418			v, ok := attnVariantFor(attn)
419			if !ok {
420				return fmt.Errorf("vae: no attention kernel %q (have %v)", attn, AttnKernels())
421			}
422			gk := opt.GEMM
423			if gk == "" {
424				gk = DefaultGEMMKernel
425			}
426			gv, ok := gemmVariantFor(gk)
427			if !ok {
428				return fmt.Errorf("vae: no GEMM kernel %q (have %v)", gk, GEMMKernels())
429			}
430			g.attn, g.gemm = v, gv
431		}
432		if opt.Conv != ConvScalar {
433			ck := opt.Conv
434			if ck == "" {
435				ck = DefaultConvKernel
436			}
437			cv, ok := convVariantFor(ck)
438			if !ok {
439				return fmt.Errorf("vae: no conv kernel %q (have %v)", ck, ConvKernels())
440			}
441			g.conv = cv
442		}
443		return nil
444	}
445	
446	// wmma reports whether the mid block runs on the matrix cores.
447	func (e *engine) wmma() bool { return e.attn.spirv != nil }
448	
449	// convCores reports whether the convolutions do.
450	func (e *engine) convCores() bool { return e.conv.spirv != nil }
451	
452	// f16 reports whether anything in the graph needs the two fp16 arenas. They
453	// are bound to every pipeline either way -- one descriptor layout across the
454	// graph is what lets a decode be recorded into one command buffer -- but on
455	// the fully scalar path they are placeholders.
456	func (e *engine) f16() bool { return e.wmma() || e.convCores() }
457	
458	// Kernels names the graph's three chosen kernels, for a benchmark's output.
459	func (g *GPUDecoder) Kernels() (AttnKernel, GEMMKernel, ConvKernel) { return g.engine.kernels() }
460	
461	func (g *engine) kernels() (AttnKernel, GEMMKernel, ConvKernel) {
462		attn, gemm, conv := AttnScalar, GEMMKernel(""), ConvScalar
463		if g.wmma() {
464			attn, gemm = g.attn.name, g.gemm.name
465		}
466		if g.convCores() {
467			conv = g.conv.name
468		}
469		return attn, gemm, conv
470	}
