472	// pipeline builds one pipeline and records its module for destruction.
473	func (e *engine) pipeline(name string, spirv []byte, spec vk.PipelineSpec) error {
474		mod, err := e.dev.NewShaderModule(spirv)
475		if err != nil {
476			return fmt.Errorf("vae: shader %s: %w", name, err)
477		}
478		e.mods = append(e.mods, mod)
479		pipe, err := e.dev.NewPipeline(mod, spec)
480		if err != nil {
481			return fmt.Errorf("vae: pipeline %s: %w", name, err)
482		}
483		e.pipes[name] = pipe
484		return nil
485	}
