487	// newEngine is an engine with nothing staged on it yet.
488	func newEngine(dev *vk.Device) engine {
489		return engine{
490			dev:     dev,
491			pipes:   make(map[string]*vk.ComputePipeline),
492			weights: &gpuWeights{off: make(map[string]uint32)},
493			w16:     make(map[string]uint32),
494		}
495	}
