497	// bufs is the four-buffer set every pipeline in a graph is built over, in the
498	// binding order vae_common.glsl declares.
499	func (e *engine) bufs() []*vk.Buffer { return []*vk.Buffer{e.wbuf, e.abuf, e.hbuf, e.w16buf} }
500	
501	// Destroy releases every Vulkan object.
502	func (g *GPUDecoder) Destroy() { g.engine.destroy() }
503	
504	func (e *engine) destroy() {
505		for _, p := range e.pipes {
506			p.Destroy()
507		}
508		for _, m := range e.mods {
509			m.Destroy()
510		}
511		for _, b := range []*vk.Buffer{e.abuf, e.wbuf, e.hbuf, e.w16buf} {
512			if b != nil {
513				b.Destroy()
514			}
515		}
516		e.pipes, e.mods = map[string]*vk.ComputePipeline{}, nil
517		e.abuf, e.wbuf, e.hbuf, e.w16buf = nil, nil, nil, nil
518	}
