520	// flattenWeights copies every weight the graph reads into one arena, in the
521	// order the graph reads them.
522	func (g *GPUDecoder) flattenWeights() {
523		w := g.weights
524		g.convs = nil
525		conv := func(name string, c *Conv2D) {
526			w.put(name+".weight", c.Weight)
527			if c.Bias != nil {
528				w.put(name+".bias", c.Bias)
529			}
530			g.convs = append(g.convs, convRef{name, c})
531		}
532		norm := func(name string, n *GroupNorm) {
533			w.put(name+".weight", n.Weight)
534			w.put(name+".bias", n.Bias)
535		}
536		lin := func(name string, l *Linear) {
537			w.put(name+".weight", l.Weight)
538			if l.Bias != nil {
539				w.put(name+".bias", l.Bias)
540			}
541		}
542		resnet := func(name string, r *ResnetBlock) {
543			norm(name+".norm1", r.Norm1)
544			conv(name+".conv1", r.Conv1)
545			norm(name+".norm2", r.Norm2)
546			conv(name+".conv2", r.Conv2)
547			if r.Shortcut != nil {
548				conv(name+".shortcut", r.Shortcut)
549			}
550		}
551	
552		conv("conv_in", g.cpu.ConvIn)
553		resnet("mid.r1", g.cpu.Mid.Resnet1)
554		norm("mid.attn.norm", g.cpu.Mid.Attn.GroupNorm)
555		lin("mid.attn.q", g.cpu.Mid.Attn.Q)
556		lin("mid.attn.k", g.cpu.Mid.Attn.K)
557		lin("mid.attn.v", g.cpu.Mid.Attn.V)
558		lin("mid.attn.out", g.cpu.Mid.Attn.Out)
559		resnet("mid.r2", g.cpu.Mid.Resnet2)
560		for i, up := range g.cpu.UpBlocks {
561			for j, r := range up.Resnets {
562				resnet(fmt.Sprintf("up.%d.r%d", i, j), r)
563			}
564			if up.Upsampler != nil {
565				conv(fmt.Sprintf("up.%d.upconv", i), up.Upsampler)
566			}
567		}
568		norm("conv_norm_out", g.cpu.ConvNormOut)
569		conv("conv_out", g.cpu.ConvOut)
570	
571		// The matrix-core convolution starts its accumulators from the bias
572		// rather than adding it (gpu_conv.go), which wants each one repeated
573		// across a 16-wide row. A second pass, so that the arena's layout is
574		// unchanged when the convolutions run scalar.
575		if g.convCores() {
576			for _, cr := range g.convs {
577				if cr.conv.Bias != nil {
578					w.put(cr.name+".bias16", expandBias(cr.conv.Bias, cr.conv.OutC))
579				}
580			}
581		}
582	}
583	
584	// tensor is a shape plus its offset in the activation arena.
585	type tensor struct {
586		off     uint32
587		C, H, W int
588	}
589	
590	func (t tensor) elems() int { return t.C * t.H * t.W }
591	
592	// builder records the decode graph into a dispatch list.
593	type builder struct {
594		e     *engine
595		ar    *arena
596		har   *arena
597		out   []vk.MultiDispatch
598		kinds []string
599		flops []float64
600	
601		pendingKind  string
602		pendingFlops float64
603	
604		// marks names the tensor a submodule leaves behind, and the dispatch that
605		// finishes it. It is what GPUEncoder.RunTo reads: a graph of 122
606		// dispatches over a bump-allocated arena overwrites every intermediate
607		// long before it ends, so the only way to look at one is to re-run the
608		// prefix and stop. zimage/dit's GPUBlock.RunTo is the same facility for
609		// the same reason, and PIPELINE.md's stagewise rule is why both exist.
610		marks map[string]tensor
611		order []string
612		stops []int
613	
614		err error
615	}
616	
617	// mark records the tensor a named submodule produced, at the graph's current
618	// length. Recording nothing costs nothing: a builder with no marks map -- the
619	// sizing and dispatch-counting passes -- skips it.
620	func (b *builder) mark(name string, t tensor) tensor {
621		if b.marks != nil {
622			b.marks[name] = t
623			b.order = append(b.order, name)
624			b.stops = append(b.stops, len(b.out))
625		}
626		return t
627	}
628	
629	// label names the next dispatch for the profiler and records its arithmetic.
630	func (b *builder) label(kind string, flops float64) {
631		b.pendingKind, b.pendingFlops = kind, flops
632	}
633	
634	func groups(n, local int) uint32 { return uint32((n + local - 1) / local) }
635	
636	func (b *builder) add(pipe string, gx uint32, pc pushConstants) {
637		b.addXY(pipe, gx, 1, pc)
638	}
639	
640	// addXY records a dispatch with a two-dimensional grid. The convolution uses
641	// it: x covers spatial tiles and y covers output channels, so one workgroup
642	// owns one channel's filter and can stage it through shared memory.
643	func (b *builder) addXY(pipe string, gx, gy uint32, pc pushConstants) {
644		if b.err != nil {
645			return
646		}
647		// planSize records the same graph with no pipelines built, purely to
648		// size the arena, so a missing pipeline is an error only once there are
649		// any at all.
650		p := b.e.pipes[pipe]
651		if p == nil && len(b.e.pipes) > 0 {
652			b.err = fmt.Errorf("vae: no pipeline %q", pipe)
653			return
654		}
655		b.out = append(b.out, vk.MultiDispatch{Pipeline: p, GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
656		kind := b.pendingKind
657		if kind == "" {
658			kind = pipe
659		}
660		b.kinds = append(b.kinds, kind)
661		b.flops = append(b.flops, b.pendingFlops)
662		b.pendingKind, b.pendingFlops = "", 0
663	}
664	
665	// release marks tensors dead so their memory can back later ones.
666	func (b *builder) release(ts ...tensor) {
667		for _, t := range ts {
668			b.ar.release(t.off, t.elems())
669		}
670	}
671	
672	func (b *builder) wOff(name string) uint32 {
673		off, ok := b.e.weights.off[name]
674		if !ok && b.err == nil {
675			b.err = fmt.Errorf("vae: no weight %q", name)
676		}
677		return off
678	}
679	
680	func (b *builder) bOff(name string) uint32 {
681		if off, ok := b.e.weights.off[name]; ok {
682			return off
683		}
684		return noBias
685	}
686	
687	// conv appends a convolution producing a fresh tensor. Both shapes this
688	// decoder uses -- 3x3 pad 1 and the 1x1 pad 0 shortcuts -- preserve H and W.
689	func (b *builder) conv(name string, c *Conv2D, x tensor) tensor {
690		if b.e.convCores() {
691			return b.convCores(name, c, x)
692		}
693		out := tensor{off: b.ar.alloc(c.OutC * x.H * x.W), C: c.OutC, H: x.H, W: x.W}
694		b.label(convLabel(c, x), convFlops(c, x))
695		// The grid's y axis is output-channel *blocks*: the shader's OC_BLOCK
696		// accumulators per thread are what give the kernel its arithmetic
697		// intensity, so the channel count is divided by that here.
698		const convOCBlock = 8
699		b.addXY("conv2d", groups(out.H*out.W, 256), groups(c.OutC, convOCBlock), pushConstants{
700			InOff: x.off, OutOff: out.off,
701			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
702			OC: uint32(c.OutC), KH: uint32(c.KH), KW: uint32(c.KW), Pad: uint32(c.Pad),
703			WOff: b.wOff(name + ".weight"), BOff: b.bOff(name + ".bias"),
704		})
705		return out
706	}
707	
708	// norm appends a group norm in place.
709	func (b *builder) norm(name string, n *GroupNorm, x tensor) tensor {
710		b.add("groupnorm", uint32(n.Groups), pushConstants{
711			InOff: x.off, OutOff: x.off,
712			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
713			WOff: b.wOff(name + ".weight"), BOff: b.wOff(name + ".bias"),
714			Groups: uint32(n.Groups),
715			Aux0:   math.Float32bits(float32(n.Eps)),
716		})
717		return x
718	}
719	
720	// silu appends an in-place SiLU.
721	func (b *builder) silu(x tensor) tensor {
722		b.add("silu", groups(x.elems(), 256), pushConstants{
723			InOff: x.off, OutOff: x.off, Aux0: uint32(x.elems()),
724		})
725		return x
726	}
727	
728	// addInto appends out = a + res, writing into a.
729	func (b *builder) addInto(a, res tensor) tensor {
730		b.add("add", groups(a.elems(), 256), pushConstants{
731			InOff: a.off, OutOff: a.off, ResOff: res.off, Aux0: uint32(a.elems()),
732		})
733		return a
734	}
735	
736	func (b *builder) resnet(name string, r *ResnetBlock, x tensor) tensor {
737		// norm1 writes into a fresh tensor rather than over x, because x is the
738		// residual and is read again at the end of the block.
739		//
740		// Every release below happens *after* the dispatch that consumes the
741		// tensor has been recorded, and after the next tensor has been
742		// allocated. Releasing earlier would let the allocator hand the same
743		// block to a tensor that is still being read from it.
744		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
745		b.add("groupnorm", uint32(r.Norm1.Groups), pushConstants{
746			InOff: x.off, OutOff: h.off,
747			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
748			WOff: b.wOff(name + ".norm1.weight"), BOff: b.wOff(name + ".norm1.bias"),
749			Groups: uint32(r.Norm1.Groups), Aux0: math.Float32bits(float32(r.Norm1.Eps)),
750		})
751		h = b.silu(h)
752	
753		h1 := b.conv(name+".conv1", r.Conv1, h)
754		b.release(h)
755		h1 = b.norm(name+".norm2", r.Norm2, h1)
756		h1 = b.silu(h1)
757	
758		h2 := b.conv(name+".conv2", r.Conv2, h1)
759		b.release(h1)
760	
761		skip := x
762		if r.Shortcut != nil {
763			skip = b.conv(name+".shortcut", r.Shortcut, x)
764		}
765		out := b.addInto(h2, skip)
766		if r.Shortcut != nil {
767			b.release(skip)
768		}
769		b.release(x)
770		return out
771	}
772	
773	func (b *builder) attention(name string, a *Attention, x tensor) tensor {
774		rows := x.H * x.W
775		dim := a.Q.Out
776	
777		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
778		b.add("groupnorm", uint32(a.GroupNorm.Groups), pushConstants{
779			InOff: x.off, OutOff: h.off,
780			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
781			WOff: b.wOff(name + ".norm.weight"), BOff: b.wOff(name + ".norm.bias"),
782			Groups: uint32(a.GroupNorm.Groups), Aux0: math.Float32bits(float32(a.GroupNorm.Eps)),
783		})
784	
785		seq := tensor{off: b.ar.alloc(rows * x.C), C: x.C, H: x.H, W: x.W}
786		b.add("to_rows", groups(rows*x.C, 256), pushConstants{
787			InOff: h.off, OutOff: seq.off,
788			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
789		})
790	
791		proj := func(pname string, l *Linear) tensor {
792			out := tensor{off: b.ar.alloc(rows * l.Out), C: l.Out, H: x.H, W: x.W}
793			b.label(fmt.Sprintf("linear %d->%d x%d", l.In, l.Out, rows),
794				2*float64(rows)*float64(l.Out)*float64(l.In))
795			b.add("linear", groups(rows*l.Out, 64), pushConstants{
796				InOff: seq.off, OutOff: out.off,
797				C: uint32(l.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(l.Out),
798				WOff: b.wOff(pname + ".weight"), BOff: b.bOff(pname + ".bias"),
799			})
800			return out
801		}
802		q := proj(name+".q", a.Q)
803		k := proj(name+".k", a.K)
804		v := proj(name+".v", a.V)
805	
806		// Transpose K so the score loop reads consecutive keys at consecutive
807		// addresses (IDEAS §5.1b). The +64 pads the destination row stride off a
808		// multiple of the 4 KB channel rotation, which is what puts the gcd
809		// inside §5.1b's [128, 256] byte window.
810		kStride := rows + 64
811		kT := tensor{off: b.ar.alloc(dim * kStride), C: dim, H: 1, W: kStride}
812		b.label(fmt.Sprintf("transpose %dx%d", rows, dim), 0)
813		b.add("transpose", groups(rows*dim, 256), pushConstants{
814			InOff: k.off, OutOff: kT.off,
815			C: uint32(dim), Aux0: uint32(rows), Aux1: uint32(kStride),
816		})
817	
818		ctx := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
819		// Two passes of q.k plus the weighted sum of v, all over rows x rows.
820		b.label(fmt.Sprintf("attention %d rows x %d", rows, dim),
821			3*2*float64(rows)*float64(rows)*float64(dim))
822		b.add("attention", uint32(rows), pushConstants{
823			InOff: q.off, OutOff: ctx.off, ResOff: kT.off,
824			C:      uint32(dim),
825			Groups: uint32(kStride),
826			Aux0:   uint32(rows), Aux1: math.Float32bits(float32(a.Scale)), Aux2: v.off,
827		})
828	
829		outRows := tensor{off: b.ar.alloc(rows * a.Out.Out), C: a.Out.Out, H: x.H, W: x.W}
830		b.label(fmt.Sprintf("linear %d->%d x%d", a.Out.In, a.Out.Out, rows),
831			2*float64(rows)*float64(a.Out.Out)*float64(a.Out.In))
832		b.add("linear", groups(rows*a.Out.Out, 64), pushConstants{
833			InOff: ctx.off, OutOff: outRows.off,
834			C: uint32(a.Out.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(a.Out.Out),
835			WOff: b.wOff(name + ".out.weight"), BOff: b.bOff(name + ".out.bias"),
836		})
837	
838		res := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
839		// The bias is in the projection above on this path, so the fused add has
840		// none of its own -- there is no push-constant value that means "not set"
841		// (stage 6), so it is said explicitly.
842		b.add("to_nchw", groups(x.elems(), 256), pushConstants{
843			InOff: outRows.off, OutOff: res.off, ResOff: x.off,
844			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
845			Aux0: noBias,
846		})
847		b.release(h, seq, q, k, kT, v, ctx, outRows, x)
848		return res
849	}
850	
851	func (b *builder) upsample(name string, c *Conv2D, x tensor) tensor {
852		up := tensor{off: b.ar.alloc(x.C * x.H * 2 * x.W * 2), C: x.C, H: x.H * 2, W: x.W * 2}
853		b.add("upsample2x", groups(up.elems(), 256), pushConstants{
854			InOff: x.off, OutOff: up.off,
855			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
856		})
857		b.release(x)
858		out := b.conv(name, c, up)
859		b.release(up)
860		return out
861	}
862	
863	// build records the whole decode and returns the output tensor.
864	func (b *builder) build(d *Decoder, latentH, latentW int) tensor {
865		x := tensor{off: b.ar.alloc(d.ConvIn.InC * latentH * latentW), C: d.ConvIn.InC, H: latentH, W: latentW}
866		h := b.conv("conv_in", d.ConvIn, x)
867		h = b.resnet("mid.r1", d.Mid.Resnet1, h)
868		if b.e.wmma() {
869			h = b.attentionWMMA("mid.attn", d.Mid.Attn, h)
870		} else {
871			h = b.attention("mid.attn", d.Mid.Attn, h)
872		}
873		h = b.resnet("mid.r2", d.Mid.Resnet2, h)
874		for i, up := range d.UpBlocks {
875			for j, r := range up.Resnets {
876				h = b.resnet(fmt.Sprintf("up.%d.r%d", i, j), r, h)
877			}
878			if up.Upsampler != nil {
879				h = b.upsample(fmt.Sprintf("up.%d.upconv", i), up.Upsampler, h)
880			}
881		}
882		h = b.norm("conv_norm_out", d.ConvNormOut, h)
883		h = b.silu(h)
884		out := b.conv("conv_out", d.ConvOut, h)
885		b.release(h)
886		return out
887	}
888	
889	// planSize records the graph with no pipelines bound, purely to find how
890	// large each of the two activation arenas has to be.
891	func (g *GPUDecoder) planSize(latentH, latentW int) (uint32, uint32, error) {
892		saved := g.pipes
893		g.pipes = map[string]*vk.ComputePipeline{}
894		b := &builder{e: &g.engine, ar: &arena{}, har: &arena{}}
895		b.build(g.cpu, latentH, latentW)
896		g.pipes = saved
897		if b.err != nil {
898			return 0, 0, b.err
899		}
900		return b.ar.high, b.har.high, nil
901	}
902	
903	// Apply decodes a latent on the GPU. The whole graph -- 100-odd dispatches
904	// -- is recorded into one command buffer and submitted once, with a barrier
905	// between every pair, because each stage reads what the previous wrote.
906	func (g *GPUDecoder) Apply(latent *Tensor) (*Tensor, error) {
907		if latent.N != 1 {
908			return nil, fmt.Errorf("vae: GPU decoder handles one image at a time, got N=%d", latent.N)
909		}
910		if latent.C != g.cpu.ConvIn.InC {
911			return nil, fmt.Errorf("vae: latent has %d channels, conv_in takes %d", latent.C, g.cpu.ConvIn.InC)
912		}
913	
914		g.arena.reset()
915		g.harena.reset()
916		b := &builder{e: &g.engine, ar: &g.arena, har: &g.harena}
917		out := b.build(g.cpu, latent.H, latent.W)
918		if b.err != nil {
919			return nil, b.err
920		}
921		if int(b.har.high)*2 > g.hbuf.Size() {
922			return nil, fmt.Errorf("vae: graph needs %d MB of fp16 activations, arena is %d MB",
923				(int(b.har.high)*2)>>20, g.hbuf.Size()>>20)
924		}
925		if int(b.ar.high)*4 > g.abuf.Size() {
926			return nil, fmt.Errorf("vae: graph needs %d MB of activations, arena is %d MB",
927				(int(b.ar.high)*4)>>20, g.abuf.Size()>>20)
928		}
929	
930		// The input tensor is the arena's first allocation, so the latent goes
931		// in at offset 0.
932		g.abuf.WriteFloat32(latent.Data)
933	
934		// Submit in batches rather than as one command buffer. The whole graph
935		// in a single submit is 5.5 s of GPU work at a 1024x1024 image, which
936		// trips the driver's reset watchdog and comes back as VK_ERROR_DEVICE_LOST
937		// -- the same 119 dispatches submitted separately all complete. Batching
938		// keeps each submit short while still amortising the per-submit fence
939		// wait over a useful number of dispatches.
940		//
941		// The batch is 4 and not 8 because the graph is not flat. It was the
942		// mid-block attention that forced it -- 1.5 s in one dispatch at a
943		// 1024x1024 image, which put a batch of eight over the watchdog on its
944		// own -- and stage 7 has since made that dispatch 15 ms, leaving a 404 ms
945		// convolution as the largest thing in the graph. So the cap is no longer
946		// load-bearing at this size, and it stays where it is because it is free:
947		// 8 measures 3.62 s against 4's 3.64, and 4 against 2 was the same 1%
948		// before that. The fence wait per submit is not what this decode is made
949		// of.
950		//
951		// Ordering and correctness are unaffected: DispatchMultiTimed blocks
952		// until its batch completes, so a batch boundary is a stronger barrier
953		// than the one already recorded between every pair of dispatches.
954		for i := 0; i < len(b.out); i += dispatchesPerSubmit {
955			j := min(i+dispatchesPerSubmit, len(b.out))
956			if _, err := vk.DispatchMultiTimed(b.out[i:j], 1, 1, true); err != nil {
957				return nil, fmt.Errorf("vae: dispatch %d-%d: %w", i, j-1, err)
958			}
959		}
960	
961		res := NewTensor(1, out.C, out.H, out.W)
962		copy(res.Data, g.abuf.ReadFloat32At(int(out.off), out.elems()))
963		return res, nil
964	}
965	
966	// Dispatches is the number of GPU dispatches one decode records, which is
967	// the figure IDEAS §4.1's 300 ns launch cost applies to.
968	func (g *GPUDecoder) Dispatches(latentH, latentW int) (int, error) {
969		saved := g.pipes
970		g.pipes = map[string]*vk.ComputePipeline{}
971		b := &builder{e: &g.engine, ar: &arena{}, har: &arena{}}
972		b.build(g.cpu, latentH, latentW)
973		g.pipes = saved
974		if b.err != nil {
975			return 0, b.err
976		}
977		return len(b.out), nil
978	}
979	
980	// ActivationBytes is the size of the fp32 activation arena.
981	func (g *GPUDecoder) ActivationBytes() int { return g.abuf.Size() }
982	
983	// F16ActivationBytes is the size of the fp16 one, which stage 8 turned from
984	// the mid block's scratch into the second-largest allocation in the decoder:
985	// the blocked copy of a convolution's input is half the tensor's own size,
986	// and at 1024x1024 the largest of them is 539 MB.
987	func (g *GPUDecoder) F16ActivationBytes() int { return g.hbuf.Size() }
988	
989	// WeightBytes is the two weight arenas: the fp32 originals every scalar
990	// kernel still reads, and the fp16 fragment-tile copies the matrix-core
991	// kernels do.
992	func (g *GPUDecoder) WeightBytes() (fp32, fp16 int) {
993		return g.wbuf.Size(), g.w16buf.Size()
994	}
995	
996	// Stage is one dispatch's identity and cost, as returned by Profile.
997	type Stage struct {
998		Index int
999		Kind  string
1000		GPU   time.Duration
1001		// Flops is the multiply-accumulate count the dispatch performs, x2, so
1002		// it can be put against the ceilings in research/roofline terms.
1003		Flops float64
1004	}
1005	
1006	// Profile runs the graph one dispatch at a time, timing each on the GPU.
1007	// Submitting separately costs a fence wait per dispatch, so the total here
1008	// is above what Apply measures -- what it is for is the *distribution*, i.e.
1009	// which stage to fix.
1010	func (g *GPUDecoder) Profile(latent *Tensor) ([]Stage, error) {
1011		g.arena.reset()
1012		g.harena.reset()
1013		b := &builder{e: &g.engine, ar: &g.arena, har: &g.harena}
1014		out := b.build(g.cpu, latent.H, latent.W)
1015		if b.err != nil {
1016			return nil, b.err
1017		}
1018		_ = out
1019		g.abuf.WriteFloat32(latent.Data)
1020	
1021		stages := make([]Stage, 0, len(b.out))
1022		for i, d := range b.out {
1023			dur, err := d.Pipeline.DispatchTimed(d.GroupsX, d.GroupsY, 1, 1, d.PushConstants)
1024			if err != nil {
1025				return stages, fmt.Errorf("vae: dispatch %d (%s): %w", i, b.kinds[i], err)
1026			}
1027			stages = append(stages, Stage{Index: i, Kind: b.kinds[i], GPU: dur, Flops: b.flops[i]})
1028		}
1029		return stages, nil
1030	}
