13		zvae "strix-halo-vulkan/zimage/vae"
14	)
15	
16	// The reference comes from reference/dump_qi21_vae.py: diffusers' VAE in
17	// fp32 on CPU, decode from seeded noise and encode of a deterministic RGBA
18	// test card, with every stage hooked. Regenerate with:
19	//
20	//	.venv/bin/python reference/dump_qi21_vae.py
21	const (
22		refDir = "../../reference/out/qi21vae"
23		vaeDir = "../../models/Qwen-Image-2.1/vae"
24	)
25	
26	type manifest struct {
27		Cases map[string]struct {
28			H      int   `json:"h"`
29			W      int   `json:"w"`
30			Latent []int `json:"latent"`
31		} `json:"cases"`
32		Tensors map[string]struct {
33			Shape []int   `json:"shape"`
34			Count int     `json:"count"`
35			Sum   float64 `json:"sum"`
36		} `json:"tensors"`
37	}
38	
39	func loadManifest(t *testing.T) *manifest {
40		t.Helper()
41		buf, err := os.ReadFile(filepath.Join(refDir, "manifest.json"))
42		if err != nil {
43			t.Skipf("no reference dump in %s (%v); run reference/dump_qi21_vae.py", refDir, err)
44		}
45		var m manifest
46		if err := json.Unmarshal(buf, &m); err != nil {
47			t.Fatal(err)
48		}
49		return &m
50	}
51	
52	// loadRef reads a dumped [1, C, 1, H, W] tensor with the frame axis folded
53	// away.
54	func loadRef(t *testing.T, m *manifest, name string) *zvae.Tensor {
55		t.Helper()
56		meta, ok := m.Tensors[name]
57		if !ok {
58			t.Fatalf("reference has no tensor %q", name)
59		}
60		raw, err := os.ReadFile(filepath.Join(refDir, name+".bin"))
61		if err != nil {
62			t.Fatal(err)
63		}
64		if len(raw) != meta.Count*4 {
65			t.Fatalf("%s: %d bytes for %d float32", name, len(raw), meta.Count)
66		}
67		sh := meta.Shape
68		if len(sh) != 5 || sh[0] != 1 || sh[2] != 1 {
69			t.Fatalf("%s: shape %v, want [1 C 1 H W]", name, sh)
70		}
71		out := zvae.NewTensor(1, sh[1], sh[3], sh[4])
72		for i := range out.Data {
73			out.Data[i] = math.Float32frombits(binary.LittleEndian.Uint32(raw[i*4:]))
74		}
75		return out
76	}
77	
78	// relTol is the fp32 bound, the same instrument as the DiT tests': both
79	// sides fp32, summation order the only drift, the rms floor keeping the
80	// decoder's enormous intermediates (absmax ~3e5) from hiding real errors on
81	// small elements.
82	const relTol = 2e-4
83	
84	// normTol is the bound for the stages where this model amplifies fp32
85	// noise, and it is measured, not chosen (all numbers 2026-09-20):
86	//
87	//   - the decoder past its tail norm: the up blocks run at magnitudes ~1e4,
88	//     where a summation-order difference is a real absolute quantity; the
89	//     per-pixel L2 norm rescales to O(1) and the inherited drift surfaces
90	//     elementwise. Against a float64 decode the dumped fp32 run is itself
91	//     rel 1.3e-3 at norm_out (3.4e-4 at the image), and changing only its
92	//     thread count moves it 8.6e-4. This port's decoded image sits max abs
93	//     8.7e-4 from the dump in [-1, 1] — under a quarter of one 8-bit
94	//     quantization step;
95	//   - the encoder's deep middle: the reference's own thread-order noise
96	//     jumps 47x at down_blocks.3 (4.6e-6 → 2.2e-4, still 2.1e-4 at the mid
97	//     block) and re-contracts to 8e-6 at the posterior mode. This port
98	//     tracks at a consistent ~5x that self-noise through the same stages
99	//     and lands at 4.7e-5 on the mode, which keeps the tight bound.
100	//
101	// A structural mistake shows at rel ≥ 1e-1 on every one of these stages, so
102	// the loosened bound still catches every modeled error.
103	const normTol = 8e-3
104	
105	// tolFor picks the bound by stage, per the measurements above.
106	func tolFor(name string) float64 {
107		loose := []string{
108			"dec_norm_out", "dec_nonlinearity", "dec_conv_out", "decoded", "roundtrip",
109			"enc_down_blocks.3", "enc_down_blocks.4", "enc_mid_block", "enc_norm_out", "enc_nonlinearity",
110		}
111		for _, s := range loose {
112			if strings.HasSuffix(name, s) {
113				return normTol
114			}
115		}
116		return relTol
117	}
118	
119	func compare(t *testing.T, name string, got, want *zvae.Tensor) {
120		t.Helper()
121		if got.C != want.C || got.H != want.H || got.W != want.W {
122			t.Fatalf("%s: shape %s, want %s", name, got, want)
123		}
124		var sumSq float64
125		for i := range want.Data {
126			w := float64(want.Data[i])
127			sumSq += w * w
128		}
129		rms := math.Sqrt(sumSq / float64(len(want.Data)))
130		var maxAbs, rel float64
131		var worst int
132		for i := range want.Data {
133			d := math.Abs(float64(got.Data[i]) - float64(want.Data[i]))
134			if d > maxAbs {
135				maxAbs = d
136			}
137			if r := d / math.Max(math.Abs(float64(want.Data[i])), math.Max(rms, 1e-12)); r > rel {
138				rel, worst = r, i
139			}
140		}
141		if tol := tolFor(name); rel > tol {
142			t.Errorf("%s %s: max abs %.6g, worst rel %.3g at %d (got %g want %g), rms %.6g > %.0e",
143				name, got, maxAbs, rel, worst, got.Data[worst], want.Data[worst], rms, tol)
144			return
145		}
146		t.Logf("%-22s %-18s max abs %.3g  rms %.4g  rel %.2g", name, got.String(), maxAbs, rms, rel)
147	}
148	
149	// TestDecoder walks the decoder stage by stage — conv_in, mid, every up
150	// block, the tail — and the clamped image, for the square and rectangular
151	// cases. The DupUp shortcuts, the reference's temporal-slice semantics
152	// included, are inside up_blocks.0-3.
153	func TestDecoder(t *testing.T) {
154		m := loadManifest(t)
155		cfg, err := LoadConfig(vaeDir)
156		if err != nil {
157			t.Skipf("no VAE checkpoint at %s (%v)", vaeDir, err)
158		}
159		dec, err := LoadDecoder(vaeDir, cfg)
160		if err != nil {
161			t.Fatal(err)
162		}
163		for label := range m.Cases {
164			z := loadRef(t, m, label+"_z_norm")
165			cfg.Denormalize(z)
166			dec.Tap = func(name string, x *zvae.Tensor) {
167				compare(t, label+"_dec_"+name, x, loadRef(t, m, label+"_dec_"+name))
168			}
169			img, err := dec.Decode(z)
170			dec.Tap = nil
171			if err != nil {
172				t.Fatal(err)
173			}
174			compare(t, label+"_decoded", img, loadRef(t, m, label+"_decoded"))
175		}
176	}
177	
178	// TestEncoder walks the encoder the same way — the AvgDown shortcuts with
179	// their zero-frame means are inside down_blocks.1-3 — through to the
180	// posterior mode, raw and normalized.
181	func TestEncoder(t *testing.T) {
182		m := loadManifest(t)
183		cfg, err := LoadConfig(vaeDir)
184		if err != nil {
185			t.Skipf("no VAE checkpoint at %s (%v)", vaeDir, err)
