1	#version 450
2	// Direct 2-D convolution, stride 1, symmetric zero padding, weights in
3	// PyTorch's [OC, IC, KH, KW] order. Covers both shapes the decoder uses:
4	// 3x3 pad 1 and the 1x1 pad 0 residual shortcuts.
5	//
6	// Each thread owns one output pixel and OC_BLOCK output channels, so the
7	// activation window it reads is multiplied into OC_BLOCK accumulators held
8	// in registers. The grid is (spatial tiles, output-channel blocks) and each
9	// workgroup stages its slice of the filter through shared memory, a block of
10	// input channels at a time.
11	//
12	// The register blocking is the load-bearing part, and it is IDEAS §2.1's
13	// result applied to a different operator. Profiling the first version of
14	// this decoder put conv3x3 at 90.3% of the whole decode at ~750 GFLOP/s,
15	// 3% of this part's measured 22.9 TFLOP/s fp32 FMA ceiling. Staging the
16	// weights in shared memory -- i.e. fixing the *weight* traffic -- moved that
17	// only to ~850, which is what said the weights were never the problem: the
18	// kernel re-reads each activation once per output channel, and the fix is to
19	// raise arithmetic intensity by computing several channels per read rather
20	// than to move bytes closer.
21	//
22	// Input-channel blocking keeps the LDS footprint off the occupancy: the full
23	// 512-channel filter for eight output channels would be 147 KB, a 32-channel
24	// block of it is 9 KB.
25	
26	#include "vae_common.glsl"
27	
28	layout(local_size_x = 256) in;
29	
30	const uint OC_BLOCK = 8u;
31	const uint IC_BLOCK = 32u;
32	const uint MAX_TAPS = 9u;
33	
34	shared float shW[OC_BLOCK * IC_BLOCK * MAX_TAPS];
35	
36	void main() {
37	    uint ocBase = gl_WorkGroupID.y * OC_BLOCK;
38	    uint t = gl_LocalInvocationID.x;
39	    uint outHW = pc.H * pc.W;                 // stride 1 with pad preserves H,W
40	    uint p = gl_WorkGroupID.x * 256u + t;     // this thread's output pixel
41	
42	    uint ow = p % pc.W;
43	    uint oh = p / pc.W;
44	    bool live = p < outHW;
45	
46	    uint taps = pc.KH * pc.KW;
47	
48	    float acc[OC_BLOCK];
49	    for (uint o = 0u; o < OC_BLOCK; ++o) {
50	        uint oc = ocBase + o;
51	        acc[o] = (oc < pc.OC && pc.bOff != NO_BIAS) ? wbuf[pc.bOff + oc] : 0.0;
52	    }
53	
54	    for (uint ic0 = 0u; ic0 < pc.C; ic0 += IC_BLOCK) {
55	        uint n = min(IC_BLOCK, pc.C - ic0);
56	        uint span = OC_BLOCK * n * taps;
57	        barrier();
58	        for (uint i = t; i < span; i += 256u) {
59	            uint o = i / (n * taps);
60	            uint rem = i - o * n * taps;
61	            uint icl = rem / taps;
62	            uint tap = rem - icl * taps;
63	            uint oc = ocBase + o;
64	            float v = 0.0;
65	            if (oc < pc.OC) {
