1	package pipeline
2	
3	import (
4		"math"
5		"runtime"
6		"testing"
7	
8		"strix-halo-vulkan/qimage/dit"
9		"strix-halo-vulkan/qimage/textenc"
10		qvae "strix-halo-vulkan/qimage/vae"
11		"strix-halo-vulkan/zimage/qwen"
12		"strix-halo-vulkan/zimage/tokenizer"
13		zvae "strix-halo-vulkan/zimage/vae"
14	)
15	
16	const (
17		model     = "../../models/Qwen-Image-2.1"
18		imgSpec   = 2.2e-2 // Z-Image's end-to-end precedent, in [0, 1] image space
19		embedSpec = 1e-3   // textenc's own deep bound; localizes a text-side break
20	)
21	
22	// TestEndToEndImage is the gate Q3 owed to Q5: prompt → image through this
23	// repo's own tokenizer, text encoder, DiT, scheduler and VAE decoder — only
24	// the initial noise comes from the oracle, as data — against the 256²/4-step
25	// reference image. The three component gates do not compose into this claim;
26	// this is the measurement. ~65 GB of fp32 weights pass through, sequenced so
27	// the peak stays near the text encoder's 34 GB; it must run alone on the
28	// machine (the full oracle run and this test together OOM'd it once).
29	func TestEndToEndImage(t *testing.T) {
30		if testing.Short() {
31			t.Skip("loads the whole fp32 pipeline, ~10 min")
32		}
33		m := loadRunManifest(t)
34	
35		// --- text: tokenize and encode the oracle's prompt ourselves.
36		tcfg, err := textenc.LoadConfig(model + "/text_encoder")
37		if err != nil {
38			t.Skipf("no checkpoint at %s (%v)", model, err)
39		}
40		tok, err := tokenizer.Load(model + "/processor")
41		if err != nil {
42			t.Fatal(err)
43		}
44		ids, err := textenc.EncodePrompt(tok, m.Prompt)
45		if err != nil {
46			t.Fatal(err)
47		}
48		drop, err := textenc.DropTokens(tok)
49		if err != nil {
50			t.Fatal(err)
51		}
52		te, err := qwen.LoadWith(model+"/text_encoder", tcfg, tcfg.NumLayers)
53		if err != nil {
54			t.Fatal(err)
55		}
56		out, err := te.Forward(ids, nil)
57		if err != nil {
58			t.Fatal(err)
59		}
60		embeds, err := textenc.Drop(out, drop)
61		if err != nil {
62			t.Fatal(err)
63		}
64		embeds = embeds.Clone()
65		te = nil
66		runtime.GC()
67		compareStepAt(t, "prompt_embeds", embeds, loadRunMat(t, m, "prompt_embeds"), embedSpec)
68	
69		// --- denoise from the oracle's noise.
70		dcfg, err := dit.LoadConfig(model + "/transformer")
71		if err != nil {
72			t.Fatal(err)
73		}
74		dm, err := dit.Load(model+"/transformer", dcfg.NumLayers)
75		if err != nil {
76			t.Fatal(err)
77		}
78		side := m.Size / 16
79		lay, err := dit.NewLayout([]int{embeds.Rows}, [][3]int{{1, side, side}})
80		if err != nil {
81			t.Fatal(err)
82		}
83		scfg, err := LoadSchedConfig(model + "/scheduler")
84		if err != nil {
85			t.Fatal(err)
86		}
87		sched, err := scfg.Timesteps(m.Steps, side*side)
88		if err != nil {
89			t.Fatal(err)
90		}
91		latents, err := Denoise(dm, embeds, lay, nil, loadRunMat(t, m, "noise"), sched, nil)
92		if err != nil {
93			t.Fatal(err)
94		}
95		dm = nil
96		runtime.GC()
97	
98		// --- decode: unpack [tokens, C] to [1, C, h, w], denormalize, decode.
99		vcfg, err := qvae.LoadConfig(model + "/vae")
100		if err != nil {
101			t.Fatal(err)
102		}
103		dec, err := qvae.LoadDecoder(model+"/vae", vcfg)
104		if err != nil {
105			t.Fatal(err)
106		}
107		z := zvae.NewTensor(1, latents.Cols, side, side)
108		for tk := 0; tk < latents.Rows; tk++ {
109			row := latents.Row(tk)
110			for c := 0; c < latents.Cols; c++ {
111				z.Plane(0, c)[tk] = row[c]
112			}
113		}
114		vcfg.Denormalize(z)
115		img, err := dec.Decode(z)
116		if err != nil {
117			t.Fatal(err)
118		}
119	
120		// --- against the oracle's image, in its own [0, 1], HWC layout.
121		want := loadRunMat(t, m, "image") // [H*W, 4]
122		var maxAbs, sumAbs float64
123		for h := 0; h < img.H; h++ {
124			for w := 0; w < img.W; w++ {
125				for c := 0; c < img.C; c++ {
126					got := (float64(img.Plane(0, c)[h*img.W+w]) + 1) / 2
127					d := math.Abs(got - float64(want.Row(h*img.W+w)[c]))
128					if d > maxAbs {
129						maxAbs = d
130					}
131					sumAbs += d
132				}
