	if err != nil {
		t.Fatal(err)
	}
	want := map[string]string{
		"patch_embed": "vis_patch_embed",
		"block_input": "vis_block_input",
		"block0_out":  "vis_block0_out",
		"block1_out":  "vis_block1_out",
	}
