	// Both are GELUs and the difference is ~1e-3 at the knee.
	swapped := *model
	swapped.Blocks = append([]Block(nil), model.Blocks...)
	orig := geluSwap(geluErf)
	control(t, "erf GELU in the MLP", &swapped, pixels, gridH, gridW, m, "vis_block0_out")
	geluSwap(orig)

	// 3. Adjacent-pair rotation instead of NeoX halves — the DiT's
	// convention, which lives in the same repository.
	ropePairs = true
	control(t, "adjacent-pair rotation", model, pixels, gridH, gridW, m, "vis_block0_out")
	ropePairs = false

	// 4. The deepstack mergers' norm placement on the output merger. This
	// one cannot even load — the checkpoint's norm is 1152 wide and a
	// post-shuffle merger wants 4608 — so it is asserted as a load failure,
	// which is the stronger outcome.
	l := &loader{set: mustOpen(t), prefix: "model.visual."}
	defer l.set.Close()
	l.merger("merger", cfg, true)
	if l.err == nil {
		t.Error("loading the output merger as post-shuffle succeeded; the norm widths should have refused it")
	} else {
		t.Logf("post-shuffle output merger refused at load: %v", l.err)
	}
}

// control runs the two-block prefix and requires the named stage to be far
// outside the bound.
func control(t *testing.T, what string, model *Model, pixels *qwen.Mat, gridH, gridW int, m *manifest, stage string) {
	t.Helper()
	var rel float64
	want := loadRef(t, m, stage)
	_, err := model.Forward(pixels, gridH, gridW, func(name string, x *qwen.Mat) {
		if name != "block0_out" || x.Rows != want.Rows || x.Cols != want.Cols {
			return
		}
		var sumSq float64
		for _, v := range want.Data {
			sumSq += float64(v) * float64(v)
		}
		rms := math.Sqrt(sumSq / float64(len(want.Data)))
		for i := range want.Data {
			d := math.Abs(float64(x.Data[i]) - float64(want.Data[i]))
			if r := d / math.Max(math.Abs(float64(want.Data[i])), rms); r > rel {
				rel = r
			}
		}
	})
	if err != nil {
		t.Fatalf("%s: %v", what, err)
	}
	if rel <= deepTol {
		t.Errorf("%s still matches at rel %.3g, inside the %.0e bound", what, rel, deepTol)
		return
	}
	t.Logf("control %-24s rel %.3g, %.0fx the bound", what, rel, rel/deepTol)
}

func mustOpen(t *testing.T) *safetensorsSet {
	t.Helper()
	s, err := openSet(encoder)
	if err != nil {
		t.Fatal(err)
	}
	return s
}

