3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8	
9		"strix-halo-vulkan/safetensors"
10	)
11	
12	// LoadConfig reads the vision half of the text encoder's config.json.
13	func LoadConfig(dir string) (*Config, error) {
14		buf, err := os.ReadFile(filepath.Join(dir, "config.json"))
15		if err != nil {
16			return nil, err
17		}
18		var wrapper struct {
19			Vision Config `json:"vision_config"`
20		}
21		if err := json.Unmarshal(buf, &wrapper); err != nil {
22			return nil, fmt.Errorf("vision: parsing config.json: %w", err)
23		}
24		c := wrapper.Vision
25		if c.Depth == 0 || c.HiddenSize == 0 {
26			return nil, fmt.Errorf("vision: config.json has no vision_config")
27		}
28		if c.HiddenAct != "gelu_pytorch_tanh" {
29			return nil, fmt.Errorf("vision: hidden_act %q; this port implements gelu_pytorch_tanh", c.HiddenAct)
30		}
31		if c.SpatialMergeSize != 2 {
32			return nil, fmt.Errorf("vision: spatial_merge_size %d; this port implements 2", c.SpatialMergeSize)
33		}
34		if side := c.GridPerSide(); side*side != c.NumPositionEmbeddings {
35			return nil, fmt.Errorf("vision: %d position embeddings is not a square grid", c.NumPositionEmbeddings)
36		}
37		return &c, nil
38	}
39	
40	type loader struct {
41		set    *safetensors.Set
42		prefix string
43		err    error
44	}
45	
46	func (l *loader) f32(name string, want int) []float32 {
47		if l.err != nil {
48			return nil
49		}
50		t, err := l.set.Get(l.prefix + name)
51		if err != nil {
52			l.err = err
53			return nil
54		}
55		v, err := t.F32(nil)
56		if err != nil {
57			l.err = err
58			return nil
59		}
60		if want > 0 && len(v) != want {
61			l.err = fmt.Errorf("vision: %s has %d values, want %d", name, len(v), want)
62			return nil
63		}
64		return v
65	}
66	
67	func (l *loader) linear(name string, out, in int) Linear {
68		return Linear{In: in, Out: out,
69			Weight: l.f32(name+".weight", out*in),
70			Bias:   l.f32(name+".bias", out)}
71	}
72	
73	func (l *loader) norm(name string, width int) LayerNorm {
74		return LayerNorm{Weight: l.f32(name+".weight", width), Bias: l.f32(name+".bias", width)}
75	}
76	
77	// merger loads one of the four patch mergers. `post` decides where the norm
78	// sits, and the norm's own width in the checkpoint is what proves it: a
79	// post-shuffle merger normalizes the concatenated 4608, a pre-shuffle one
80	// the 1152 it came from. Loading the wrong width is an error here rather
81	// than a wrong answer later.
82	func (l *loader) merger(name string, cfg *Config, post bool) Merger {
83		merge := cfg.SpatialMergeSize * cfg.SpatialMergeSize
84		wide := cfg.HiddenSize * merge
85		normWidth := cfg.HiddenSize
86		if post {
87			normWidth = wide
88		}
89		return Merger{
90			PostShuffleNorm: post,
91			Merge:           merge,
92			Norm:            l.norm(name+".norm", normWidth),
93			FC1:             l.linear(name+".linear_fc1", wide, wide),
94			FC2:             l.linear(name+".linear_fc2", cfg.OutHiddenSize, wide),
95			// nn.GELU(), the exact one -- not the block MLP's tanh
96			// approximation. Both are in this model and they are not the same
97			// function.
98			Act: geluErf,
99		}
100	}
101	
102	// Load reads the tower out of the text encoder's safetensors.
103	//
104	// `blocks` caps how many of the 27 are loaded, which is what lets a test
105	// walk the first two without staging 1.0 GB of ViT. Zero or negative means
106	// all of them; a deepstack merger whose layer is past the cap is skipped.
107	func Load(dir string, cfg *Config, blocks int) (*Model, error) {
108		set, err := safetensors.OpenSet(dir)
109		if err != nil {
110			return nil, err
111		}
112		defer set.Close()
113		if blocks <= 0 || blocks > cfg.Depth {
114			blocks = cfg.Depth
115		}
116		l := &loader{set: set, prefix: "model.visual."}
117	
118		m := &Model{Cfg: *cfg}
119		// The Conv3d patch embedding is one linear: its kernel is exactly one
120		// patch, so [1152, 3, 2, 16, 16] is [1152, 1536] row-major already.
121		m.PatchProj = l.linear("patch_embed.proj", cfg.HiddenSize, cfg.PatchElems())
122		m.PosEmbed = l.f32("pos_embed.weight", cfg.NumPositionEmbeddings*cfg.HiddenSize)
123	
124		for i := 0; i < blocks; i++ {
125			p := fmt.Sprintf("blocks.%d.", i)
126			m.Blocks = append(m.Blocks, Block{
127				Norm1: l.norm(p+"norm1", cfg.HiddenSize),
128				Norm2: l.norm(p+"norm2", cfg.HiddenSize),
129				Attn: Attention{
130					QKV:      l.linear(p+"attn.qkv", 3*cfg.HiddenSize, cfg.HiddenSize),
131					Proj:     l.linear(p+"attn.proj", cfg.HiddenSize, cfg.HiddenSize),
132					NumHeads: cfg.NumHeads,
133				},
134				MLP: MLP{
135					FC1: l.linear(p+"mlp.linear_fc1", cfg.IntermediateSize, cfg.HiddenSize),
136					FC2: l.linear(p+"mlp.linear_fc2", cfg.HiddenSize, cfg.IntermediateSize),
137					Act: geluTanh, // config hidden_act; the mergers use the erf one
138				},
139			})
140		}
141		for j, idx := range cfg.DeepstackIndexes {
142			if idx >= blocks {
143				continue
144			}
145			m.Deepstack = append(m.Deepstack, l.merger(fmt.Sprintf("deepstack_merger_list.%d", j), cfg, true))
146		}
147		m.Merger = l.merger("merger", cfg, false)
148	
149		if l.err != nil {
150			return nil, l.err
151		}
152		return m, nil
153	}

